-- ========================================================
-- SCRIPT DE INSTALACION MAESTRO COMPLETO (ESPEJO 100% REAL)
-- BASE DE DATOS: AniDimensionDB
-- COMPATIBLE CON: SQL SERVER 2008 R2, 2012, 2014, 2016, 2017, 2019, 2022
-- ========================================================

USE master;
GO

IF EXISTS (SELECT name FROM sys.databases WHERE name = N'AniDimensionDB')
BEGIN
    ALTER DATABASE [AniDimensionDB] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [AniDimensionDB];
END
GO

CREATE DATABASE [AniDimensionDB];
GO

USE [AniDimensionDB];
GO

-- ==========================================
-- TABLA: [dbo].[AdventureEras]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[AdventureEras]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[AdventureEras] (
        [Id] INT NOT NULL,
        [Code] VARCHAR(50) NOT NULL,
        [Series] NVARCHAR(50) NOT NULL,
        [Title] NVARCHAR(100) NOT NULL,
        [Subtitle] NVARCHAR(200) NULL,
        [DescText] NVARCHAR(500) NULL,
        [Icon] VARCHAR(20) NULL,
        [BgTheme] VARCHAR(50) NULL,
        [LevelRange] VARCHAR(50) NULL,
        [AssignedPack] VARCHAR(50) NULL,
        [CreatedAt] DATETIME NULL DEFAULT (getdate()),
        CONSTRAINT [PK_AdventureEras] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

