IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[UserPlaymats]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[UserPlaymats] (
        [Id] INT IDENTITY(1,1) NOT NULL,
        [UsuarioId] INT NOT NULL,
        [PlaymatCode] VARCHAR(50) NOT NULL,
        [AcquiredAt] DATETIME NOT NULL DEFAULT (getdate()),
        CONSTRAINT [PK_UserPlaymats] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

-- ==========================================
-- TABLA: [dbo].[Users]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[Users]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[Users] (
        [Id] UNIQUEIDENTIFIER NOT NULL,
        [Username] NVARCHAR(50) NOT NULL,
        [Email] NVARCHAR(150) NOT NULL,
        [PasswordHash] NVARCHAR(MAX) NOT NULL,
        [CountryIsoCode] NVARCHAR(5) NOT NULL,
        [RoleId] INT NOT NULL,
        [CreatedAt] DATETIME2 NOT NULL,
        [LastLogin] DATETIME2 NULL,
        [IsActive] BIT NOT NULL,
        CONSTRAINT [PK_Users] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

-- ==========================================
-- TABLA: [dbo].[UserSinglePurchases]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[UserSinglePurchases]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[UserSinglePurchases] (
        [Id] INT IDENTITY(1,1) NOT NULL,
        [UsuarioId] INT NOT NULL,
        [CardCode] VARCHAR(50) NOT NULL,
        [CardName] NVARCHAR(150) NULL,
        [PriceUsd] DECIMAL(10, 2) NULL DEFAULT ((0.00)),
        [PriceStarships] INT NULL DEFAULT ((0)),
        [PaymentMethod] VARCHAR(50) NULL DEFAULT ('STARSHIPS'),
        [FoilType] VARCHAR(50) NULL DEFAULT ('NORMAL'),
        [Quantity] INT NULL DEFAULT ((1)),
        [StarshipsBalanceBefore] INT NULL,
        [StarshipsBalanceAfter] INT NULL,
        [PurchasedAt] DATETIME NULL DEFAULT (getdate()),
        CONSTRAINT [PK_UserSinglePurchases] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

-- ==========================================
-- TABLA: [dbo].[UserSleeves]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[UserSleeves]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[UserSleeves] (
        [Id] INT IDENTITY(1,1) NOT NULL,
        [UsuarioId] INT NOT NULL,
        [SleeveCode] VARCHAR(50) NOT NULL,
        [AcquiredAt] DATETIME NOT NULL DEFAULT (getdate()),
        CONSTRAINT [PK_UserSleeves] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

-- ==========================================
-- TABLA: [dbo].[UserVipPasses]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[UserVipPasses]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[UserVipPasses] (
        [Id] INT IDENTITY(1,1) NOT NULL,
        [UsuarioId] INT NOT NULL,
        [VipCode] VARCHAR(50) NOT NULL,
        [ExpiresAt] DATETIME NOT NULL,
        [AcquiredAt] DATETIME NOT NULL DEFAULT (getdate()),
        CONSTRAINT [PK_UserVipPasses] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

-- ==========================================
-- TABLA: [dbo].[Usuarios]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[Usuarios]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[Usuarios] (
        [Id] INT IDENTITY(1,1) NOT NULL,
        [Username] VARCHAR(50) NOT NULL,
        [PasswordHash] VARCHAR(255) NOT NULL,
        [Nivel] INT NOT NULL DEFAULT ((1)),
        [Experiencia] INT NOT NULL DEFAULT ((0)),
        [Starships] BIGINT NOT NULL DEFAULT ((500)),
        [IsAdmin] BIT NOT NULL DEFAULT ((0)),
        [FechaCreacion] DATETIME NOT NULL DEFAULT (getdate()),
        [FundaActivaId] VARCHAR(50) NULL DEFAULT ('default_sleeve'),
        [MatActivoId] VARCHAR(50) NULL DEFAULT ('default_mat'),
        [Email] VARCHAR(150) NULL,
        [CountryIsoCode] NVARCHAR(5) NULL,
        [IsActive] BIT NOT NULL DEFAULT ((1)),
        [IsBanned] BIT NOT NULL DEFAULT ((0)),
        [BannedUntil] DATETIME NULL,
        [BanReason] NVARCHAR(255) NULL,
        [AvatarActivoId] NVARCHAR(50) NOT NULL DEFAULT ('AVA-002'),
        [VipUntil] DATETIME NULL,
        [ActiveSessionToken] NVARCHAR(100) NULL,
        [LastLoginAt] DATETIME NULL,
        [IsOnline] BIT NOT NULL DEFAULT ((0)),
        [ClanCooldownUntil] DATETIME NULL,
        CONSTRAINT [PK_Usuarios] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

-- ==========================================
-- TABLA: [dbo].[VipPassesCatalog]
-- ==========================================
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[VipPassesCatalog]') AND type in (N'U'))
BEGIN
    CREATE TABLE [dbo].[VipPassesCatalog] (
        [Id] INT IDENTITY(1,1) NOT NULL,
        [Code] VARCHAR(50) NOT NULL,
        [Name] NVARCHAR(100) NOT NULL,
        [DurationDays] INT NOT NULL DEFAULT ((30)),
        [ExpBoost] DECIMAL(5, 2) NOT NULL DEFAULT ((100.00)),
        [StarshipsBoost] DECIMAL(5, 2) NOT NULL DEFAULT ((100.00)),
        [LuckBoost] DECIMAL(5, 2) NOT NULL DEFAULT ((15.00)),
        [Currency] VARCHAR(20) NOT NULL DEFAULT ('USD'),
        [PriceStarships] INT NOT NULL DEFAULT ((0)),
        [PriceUsd] DECIMAL(10, 2) NOT NULL DEFAULT ((0.00)),
        [OfferText] NVARCHAR(100) NULL,
        [IsActive] BIT NOT NULL DEFAULT ((1)),
        [CreatedAt] DATETIME NULL DEFAULT (getdate()),
        CONSTRAINT [PK_VipPassesCatalog] PRIMARY KEY CLUSTERED ([Id] ASC)
    );
END
GO

