    (1, N'LOB', 39111158, N'LOB-000', N'Tri-Horned Dragon', N'Normal Monster', 2850, 2350, 8, N'DARK', N'Dragon', N'An unworthy dragon with three sharp horns sprouting from its head.', N'SECRET_RARE', 0, 0, 1, 1, '2026-10-12 12:22:04'),
    (2, N'LOB', 89631139, N'LOB-001', N'Blue-Eyes White Dragon', N'Normal Monster', 3000, 2500, 8, N'LIGHT', N'Dragon', N'This legendary dragon is a powerful engine of destruction. Virtually invincible, very few have faced this awesome creature and lived to tell the tale.', N'ULTRA_RARE', 0, 0, 1, 1, '2026-10-12 12:22:04'),
    (3, N'LOB', 76184692, N'LOB-002', N'Hitotsu-Me Giant', N'Normal Monster', 1200, 1000, 4, N'EARTH', N'Beast-Warrior', N'A one-eyed behemoth with thick, powerful arms made for delivering punishing blows.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:04'),
    (4, N'LOB', 45231177, N'LOB-003', N'Flame Swordsman', N'Fusion Monster', 1800, 1600, 5, N'FIRE', N'Warrior', N'"Flame Manipulator" + "Masaki the Legendary Swordsman"', N'SUPER_RARE', 0, 0, 1, 1, '2026-10-12 12:22:04'),
    (5, N'LOB', 32274490, N'LOB-004', N'Skull Servant', N'Normal Monster', 300, 200, 1, N'DARK', N'Zombie', N'A skeletal ghost that isn''t strong but can mean trouble in large numbers.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:04'),
    (6, N'LOB', 36996508, N'LOB-005', N'Dark Magician', N'Normal Monster', 2500, 2100, 7, N'DARK', N'Spellcaster', N'The ultimate wizard in terms of attack and defense.', N'ULTRA_RARE', 0, 0, 1, 1, '2026-10-12 12:22:04'),
    (7, N'LOB', 6368038, N'LOB-006', N'Gaia The Fierce Knight', N'Normal Monster', 2300, 2100, 7, N'EARTH', N'Warrior', N'A knight whose horse travels faster than the wind. His battle-charge is a force to be reckoned with.', N'ULTRA_RARE', 0, 0, 1, 1, '2026-10-12 12:22:04'),
    (8, N'LOB', 91152256, N'LOB-007', N'Celtic Guardian', N'Normal Monster', 1400, 1200, 4, N'EARTH', N'Warrior', N'An elf who learned to wield a sword, he baffles enemies with lightning-swift attacks.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:04'),
