    (10, N'LOB', 40374923, N'LOB-009', N'Mammoth Graveyard', N'Normal Monster', 1200, 800, 3, N'EARTH', N'Dinosaur', N'A mammoth that protects the graves of its pack and is absolutely merciless when facing grave-robbers.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:04'),
    (11, N'LOB', 90357090, N'LOB-010', N'Silver Fang', N'Normal Monster', 1200, 800, 3, N'EARTH', N'Beast', N'A snow wolf that''s beautiful to the eye, but absolutely vicious in battle.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:04'),
    (12, N'LOB', 9159938, N'LOB-011', N'Dark Gray', N'Normal Monster', 800, 900, 3, N'EARTH', N'Beast', N'Entirely gray, this beast has rarely been seen by mortal eyes.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:04'),
