INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (401, N'PSV', 74701381, N'PSV-026', N'DNA Surgery', N'Continuous Trap', NULL, NULL, 0, N'TRAP', N'Continuous', N'Activate this card by declaring 1 Monster Type. All face-up monsters on the field become that Type.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (402, N'PSV', 296499, N'PSV-027', N'The Regulation of Tribe', N'Continuous Trap', NULL, NULL, 0, N'TRAP', N'Continuous', N'Declare 1 Type of monster. Monsters of the declared Type cannot attack. Tribute 1 monster from your side of the field during each of your Standby Phases. If you do not, this card is destroyed.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (403, N'PSV', 36280194, N'PSV-028', N'Backup Soldier', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'While there are 5 or more monsters in your Graveyard: Target up to 3 non-Effect Monsters with 1500 or less ATK in your Graveyard; add them to your hand.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (404, N'PSV', 9074847, N'PSV-029', N'Major Riot', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'You can activate this card when 1 or more of your monsters are returned from the field to your hand by your opponent''s effect. Return all Monster Cards on the field to your respective hands. Both you and your opponent then Special Summon from your hand the same number of Monster Cards on the field in face-down Defense Position.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (405, N'PSV', 36468556, N'PSV-030', N'Ceasefire', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'If a face-down Defense Position monster or an Effect Monster is on the field: Change all face-down Defense Position monsters on the field to face-up Defense Position (Flip monsters'' effects are not activated at this time), also inflict 500 damage to your opponent for each Effect Monster on the field.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (406, N'PSV', 62867251, N'PSV-031', N'Light of Intervention', N'Continuous Trap', NULL, NULL, 0, N'TRAP', N'Continuous', N'While this card is on the field, Monster Cards cannot be Set or flipped face-down. If a Monster Card would be Set, it must be Normal Summoned in face-up Defense Position.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (407, N'PSV', 8951260, N'PSV-032', N'Respect Play', N'Continuous Trap', NULL, NULL, 0, N'TRAP', N'Continuous', N'During their respective turns, each player must show their opponent their hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (408, N'PSV', 81210420, N'PSV-033', N'Magical Hats', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'During your opponent''s Battle Phase: Choose 2 Spell/Trap Cards from your Deck and 1 monster in your Main Monster Zone. Special Summon them as Normal Monsters (ATK 0/DEF 0) in face-down Defense Position, Set the chosen monster if it is face-up, and shuffle them on the field. The 2 cards chosen from your Deck are destroyed at the end of the Battle Phase, and cannot remain on the field except during this Battle Phase.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (409, N'PSV', 71044499, N'PSV-034', N'Nobleman of Crossout', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'Target 1 face-down monster on the field; destroy that target, and if you do, banish it, then, if it was a Flip monster, each player reveals their Main Deck, then banishes all cards from it with that monster''s name.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (410, N'PSV', 17449108, N'PSV-035', N'Nobleman of Extermination', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'Select, destroy, and remove from play 1 face-down Spell or Trap Card. If it was a Trap Card, both players must remove from play all copies of that card from their Decks.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (411, N'PSV', 43434803, N'PSV-036', N'The Shallow Grave', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'Each player targets 1 monster in their own GY; each player Special Summons the target from their GY in face-down Defense Position.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (412, N'PSV', 70828912, N'PSV-037', N'Premature Burial', N'Equip Spell', NULL, NULL, 0, N'SPELL', N'Equip', N'Activate this card by paying 800 LP, then target 1 monster in your Graveyard; Special Summon that target in Attack Position and equip it with this card. When this card is destroyed, destroy the equipped monster.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (413, N'PSV', 16227556, N'PSV-038', N'Inspection', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'During your opponent''s Standby Phase, you can pay 500 Life Points to randomly select 1 card in your opponent''s hand and look at it.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (414, N'PSV', 43711255, N'PSV-039', N'Prohibition', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'Activate by declaring 1 card name. Cards with that name, and their effects, cannot be used. Cards already on the field are not affected (including face-down cards).', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (415, N'PSV', 79106360, N'PSV-040', N'Morphing Jar #2', N'Flip Effect Monster', 800, 700, 3, N'EARTH', N'Rock', N'FLIP: Shuffle all monsters on the field into the Deck. Then, each player excavates cards from the top of their Deck, until they excavate the same number of monsters they shuffled into their Main Deck. Special Summon all excavated Level 4 or lower monsters in face-down Defense Position, also send the remaining cards to the Graveyard.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (416, N'PSV', 42599677, N'PSV-041', N'Flame Champion', N'Normal Monster', 1900, 1300, 5, N'FIRE', N'Pyro', N'A warrior protected by a flaming shield that nullifies any attack.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (417, N'PSV', 78984772, N'PSV-042', N'Twin-Headed Fire Dragon', N'Normal Monster', 2200, 1700, 6, N'FIRE', N'Pyro', N'Two dragons fused as one from the effects of the Big Bang.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (418, N'PSV', 5388481, N'PSV-043', N'Darkfire Soldier #1', N'Normal Monster', 1700, 1150, 4, N'FIRE', N'Pyro', N'An explosive expert from a special elite force.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (419, N'PSV', 31477025, N'PSV-044', N'Mr. Volcano', N'Normal Monster', 2100, 1300, 5, N'FIRE', N'Pyro', N'This seemingly mild-mannered creature has an extremely volatile temper.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (420, N'PSV', 78861134, N'PSV-045', N'Darkfire Soldier #2', N'Normal Monster', 1700, 1100, 4, N'FIRE', N'Pyro', N'A warrior who gained immeasurable power from the heart of a volcano.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (421, N'PSV', 4266839, N'PSV-046', N'Kiseitai', N'Effect Monster', 300, 800, 2, N'DARK', N'Fiend', N'When your opponent''s monster attacks this card in face-down Defense Position, this card becomes an Equip Spell Card equipped to the attacking monster (No damage calculation is conducted). During each of your opponent''s Standby Phases, increase your Life Points by half of the ATK of the monster equipped with this card.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (422, N'PSV', 30655537, N'PSV-047', N'Cyber Falcon', N'Normal Monster', 1400, 1200, 4, N'WIND', N'Machine', N'A jet-powered hawk that travels at the speed of sound.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (423, N'PSV', 3134241, N'PSV-048', N'Flying Kamakiri #2', N'Normal Monster', 1500, 800, 4, N'WIND', N'Insect', N'A flying mantis that feeds primarily on insects.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (424, N'PSV', 30532390, N'PSV-049', N'Sky Scout', N'Normal Monster', 1800, 600, 4, N'WIND', N'Winged Beast', N'With eyes like a hawk and a flying speed exceeding Mach 5, this monster is a master of the sky.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (425, N'PSV', 78193831, N'PSV-050', N'Buster Blader', N'Effect Monster', 2600, 2300, 7, N'EARTH', N'Warrior', N'Gains 500 ATK for each Dragon monster your opponent controls or is in their GY.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (426, N'PSV', 37580756, N'PSV-051', N'Michizure', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'When a monster is sent from the field to your GY, even during the Damage Step: Target 1 monster on the field; destroy it.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (427, N'PSV', 1918087, N'PSV-052', N'Minor Goblin Official', N'Continuous Trap', NULL, NULL, 0, N'TRAP', N'Continuous', N'You can only activate this card when your opponent''s Life Points are 3000 or less. Inflict 500 points of damage to your opponent''s Life Points during each of his/her Standby Phases.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (428, N'PSV', 37313786, N'PSV-053', N'Gamble', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'You can only activate this card when your opponent''s hand is 6 or more cards and your hand is 2 or less. Toss a coin and call heads or tails. If you call it right, draw until your hand has 5 cards. If you call it wrong, skip your next turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
    (429, N'PSV', 63689843, N'PSV-054', N'Attack and Receive', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'You can only activate this card when you take damage to your Life Points. Inflict 700 points of damage to your opponent''s Life Points. Also, inflict 300 points of damage to your opponent''s Life Points for each "Attack and Receive" card in your Graveyard.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:07'),
