INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (601, N'LOD', 49681811, N'LOD-016', N'Freed the Matchless General', N'Effect Monster', 2300, 1700, 5, N'EARTH', N'Warrior', N'Negate any Spell effects that target this card, and if you do, destroy that Spell Card. During your Draw Phase, instead of conducting your normal draw: You can add 1 Level 4 or lower Warrior-Type monster from your Deck to your hand. This card must be face-up on the field to activate and to resolve this effect.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (602, N'LOD', 76075810, N'LOD-017', N'Throwstone Unit', N'Effect Monster', 900, 2000, 4, N'EARTH', N'Warrior', N'Tribute 1 Warrior-Type monster on your side of the field to destroy 1 face-up monster on the field whose DEF is equal to or less than the ATK of this card.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (603, N'LOD', 2460565, N'LOD-018', N'Marauding Captain', N'Effect Monster', 1200, 400, 3, N'EARTH', N'Warrior', N'Your opponent cannot target Warrior monsters for attacks, except this one. When this card is Normal Summoned: You can Special Summon 1 Level 4 or lower monster from your hand.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (604, N'LOD', 49868263, N'LOD-019', N'Ryu Senshi', N'Fusion Effect Monster', 2000, 1200, 6, N'EARTH', N'Warrior', N'"Warrior Dai Grepher" + "Spirit Ryu"
A Fusion Summon of this card can only be done with the above Fusion Materials. When a Normal Trap Card is activated (Quick Effect): You can pay 1000 LP; negate that effect. This card must be face-up on the field to activate and to resolve this effect. Negate the effects of any Spell Card that targets this card and destroy it.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (605, N'LOD', 75953262, N'LOD-020', N'Warrior Dai Grepher', N'Normal Monster', 1700, 1600, 4, N'EARTH', N'Warrior', N'The warrior who can manipulate dragons. Nobody knows his mysterious past.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (606, N'LOD', 1347977, N'LOD-021', N'Mysterious Guard', N'Flip Effect Monster', 800, 1200, 3, N'EARTH', N'Spellcaster', N'FLIP: Target 1 face-up monster on the field, and if you control a face-up Warrior-Type monster, you can target 1 additional face-up monster on the field; return the first target to the top of the Deck, then return the additional target (if any) to the hand if you still control a face-up Warrior-Type monster.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (607, N'LOD', 38742075, N'LOD-022', N'Frontier Wiseman', N'Effect Monster', 1600, 800, 3, N'EARTH', N'Spellcaster', N'Negate any Spell effects that target a Warrior-Type monster you control, and if you do, destroy that card.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (608, N'LOD', 74131780, N'LOD-023', N'Exiled Force', N'Effect Monster', 1000, 1000, 4, N'EARTH', N'Warrior', N'You can Tribute this card to target 1 monster on the field; destroy that target.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (609, N'LOD', 1525329, N'LOD-024', N'The Hunter with 7 Weapons', N'Effect Monster', 1000, 600, 3, N'EARTH', N'Warrior', N'When this card is Normal Summoned, declare 1 Type of monster. When battling that Type of monster, increase the ATK of this card by 1000 points during Damage Calculation.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (610, N'LOD', 37620434, N'LOD-025', N'Shadow Tamer', N'Flip Effect Monster', 800, 700, 3, N'EARTH', N'Warrior', N'(This card is always treated as an "Archfiend" card.)
FLIP: Target 1 Fiend-Type monster your opponent controls; take control of that target until the End Phase.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
