    (612, N'LOD', 403847, N'LOD-027', N'The A. Forces', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'All Warrior-Type monsters you control gain 200 ATK for each Warrior or Spellcaster-Type monster you control.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
