    (674, N'LOD', 24623598, N'LOD-089', N'Disappear', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'Remove from play 1 card from your opponent''s Graveyard.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:08'),
