    (676, N'LOD', 93016201, N'LOD-091', N'Royal Oppression', N'Continuous Trap', NULL, NULL, 0, N'TRAP', N'Continuous', N'Either player can pay 800 Life Points to negate the Special Summon of a monster(s), and/or an effect that Special Summons a monster(s), and destroy those cards.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
    (677, N'LOD', 29401950, N'LOD-092', N'Bottomless Trap Hole', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'When your opponent Summons a monster(s) with 1500 or more ATK: Destroy that monster(s) with 1500 or more ATK, and if you do, banish it.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:08'),
