    (689, N'PGD', 31242786, N'PGD-003', N'Souleater', N'Normal Monster', 1200, 0, 4, N'EARTH', N'Fish', N'A living wonder of mystery.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (690, N'PGD', 83986578, N'PGD-004', N'King Tiger Wanghu', N'Effect Monster', 1700, 1000, 4, N'EARTH', N'Beast', N'When a monster(s) with 1400 or less ATK is Normal Summoned or Special Summoned: Destroy those monsters with 1400 or less ATK. This card must be face-up on the field to activate and to resolve this effect.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
