INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (801, N'MFC', 11321183, N'MFC-007', N'Dark Blade', N'Normal Monster', 1800, 1500, 4, N'DARK', N'Warrior', N'They say he is a dragon-manipulating warrior from the dark world. His attack is tremendous, using his great swords with vicious power.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (802, N'MFC', 47415292, N'MFC-008', N'Pitch-Dark Dragon', N'Effect Monster', 900, 600, 3, N'DARK', N'Dragon', N'Once per turn, during your Main Phase, if you control this card on the field, you can equip it to your "Dark Blade" as an Equip Spell Card, OR unequip the Union equipment and Special Summon this card in face-up Attack Position. While equipped to a monster by this card''s effect, increase the ATK/DEF of the equipped monster by 400 points. When it attacks with an ATK that is higher than the DEF of a Defense Position monster, inflict the difference as Battle Damage to your opponent''s Life Points. (1 monster can only be equipped with 1 Union Monster at a time. If the equipped monster is destroyed as a result of battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (803, N'MFC', 84814897, N'MFC-009', N'Kiryu', N'Effect Monster', 2000, 1500, 5, N'DARK', N'Dragon', N'Once per turn, during your Main Phase, if you control this card on the field, you can equip it to your "Dark Blade" as an Equip Spell Card, OR unequip the Union equipment and Special Summon this card in face-up Attack Position. While equipped to a monster by this card''s effect, increase the ATK/DEF of the equipped monster by 900 points, and you can Tribute this card to allow the equipped monster to attack your opponent''s Life Points directly this turn. (1 monster can only be equipped with 1 Union Monster at a time. If the equipped monster is destroyed as a result of battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (804, N'MFC', 10209545, N'MFC-010', N'Decayed Commander', N'Effect Monster', 1000, 1500, 4, N'EARTH', N'Zombie', N'When this card is Normal Summoned: You can Special Summon 1 "Zombie Tiger" from your hand. If this card inflicts battle damage to your opponent by a direct attack: Discard 1 random card from their hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (805, N'MFC', 47693640, N'MFC-011', N'Zombie Tiger', N'Effect Monster', 1400, 1600, 3, N'EARTH', N'Zombie', N'Once per turn, you can either: Target 1 "Decayed Commander" you control; equip this card to that target, OR: Unequip this card and Special Summon it in Attack Position. While equipped by this effect, the equipped monster gains 500 ATK/DEF. If the equipped monster destroys an opponent''s monster by battle: Discard 1 random card from their hand. (A monster can only be equipped with 1 Union monster at a time. If the equipped monster would be destroyed by battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (806, N'MFC', 73698349, N'MFC-012', N'Giant Orc', N'Effect Monster', 2200, 0, 4, N'DARK', N'Fiend', N'If this card attacks, it is changed to Defense Position at the end of the Battle Phase. You cannot change this battle position until the end of your next turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (807, N'MFC', 19086954, N'MFC-013', N'Second Goblin', N'Effect Monster', 100, 100, 1, N'DARK', N'Fiend', N'Once per turn, during your Main Phase, if you control this monster on the field, you can equip it to your "Giant Orc" as an Equip Spell Card, OR unequip the Union equipment and Special Summon this card in face-up Attack Position. While equipped to a monster by this card''s effect, you can change the equipped monster''s battle position once per turn. (1 monster can only be equipped with 1 Union Monster at a time. If the equipped monster is destroyed as a result of battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (808, N'MFC', 46571052, N'MFC-014', N'Vampiric Orchis', N'Effect Monster', 1700, 1000, 4, N'EARTH', N'Plant', N'When this card is Normal Summoned: You can Special Summon 1 "Des Dendle" from your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (809, N'MFC', 12965761, N'MFC-015', N'Des Dendle', N'Effect Monster', 300, 2000, 4, N'EARTH', N'Plant', N'Once per turn, during your Main Phase, if you control this monster on the field, you can equip it to your "Vampiric Orchis" as an Equip Spell Card, OR unequip the Union equipment and Special Summon this card in face-up Attack Position. While equipped to a monster by this card''s effect, each time the equipped monster destroys 1 of your opponent''s monsters, Special Summon 1 "Wicked Plant Token" (Plant-Type/EARTH/Level 1/ATK 800/DEF 800). (1 monster can only be equipped with 1 Union Monster at a time. If the equipped monster is destroyed as a result of battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (810, N'MFC', 59364406, N'MFC-016', N'Burning Beast', N'Effect Monster', 1500, 1000, 4, N'FIRE', N'Pyro', N'Once per turn, during your Main Phase, if you control this monster on the field, you can equip it to your "Freezing Beast" as an Equip Spell Card, OR unequip the Union equipment and Special Summon this card in face-up Attack Position. While equipped to a monster by this card''s effect, each time the equipped monster inflicts Battle Damage to your opponent, destroy 1 face-up Spell or Trap Card on the field. (1 monster can only be equipped with 1 Union Monster at a time. If the equipped monster is destroyed as a result of battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (811, N'MFC', 85359414, N'MFC-017', N'Freezing Beast', N'Effect Monster', 1500, 1000, 4, N'WATER', N'Aqua', N'Once per turn, during your Main Phase, if you control this monster on the field, you can equip it to your "Burning Beast" as an Equip Spell Card, OR unequip the Union equipment and Special Summon this card in face-up Attack Position. While equipped to a monster by this card''s effect, each time the equipped monster inflicts Battle Damage to your opponent, destroy 1 face-down Spell or Trap Card on the field. (1 monster can only be equipped with 1 Union Monster at a time. If the equipped monster is destroyed as a result of battle, destroy this card instead.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (812, N'MFC', 11743119, N'MFC-018', N'Union Rider', N'Effect Monster', 1000, 1000, 2, N'WIND', N'Machine', N'You can take control of up to 1 Union Monster that is currently a monster on your opponent''s side of the field, and equip it to this card. The Union Monster that is equipped to this card cannot be changed back to a monster using its own effect.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (813, N'MFC', 48148828, N'MFC-019', N'D.D. Crazy Beast', N'Effect Monster', 1400, 1400, 3, N'EARTH', N'Beast', N'A monster that this card destroys as a result of battle is removed from play.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (814, N'MFC', 84636823, N'MFC-020', N'Spell Canceller', N'Effect Monster', 1800, 1600, 5, N'WIND', N'Machine', N'Spell Cards, and their effects on the field, cannot be activated. Negate all Spell effects on the field.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (815, N'MFC', 11021521, N'MFC-021', N'Neko Mane King', N'Effect Monster', 0, 0, 1, N'EARTH', N'Beast', N'During your opponent''s turn, when this card in your possession is sent to your Graveyard by an opponent''s card effect: It becomes the End Phase of this turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (816, N'MFC', 47025270, N'MFC-022', N'Helping Robo for Combat', N'Effect Monster', 1600, 0, 4, N'LIGHT', N'Machine', N'If this card destroys an opponent''s monster by battle: Draw 1 card, then return 1 card from your hand to the bottom of the Deck.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (817, N'MFC', 73414375, N'MFC-023', N'Dimension Jar', N'Flip Effect Monster', 200, 200, 2, N'DARK', N'Machine', N'FLIP: Both players can remove from play up to 3 monsters from their opponent''s Graveyard.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (818, N'MFC', 10809984, N'MFC-024', N'Great Phantom Thief', N'Effect Monster', 1000, 1000, 3, N'EARTH', N'Spellcaster', N'If this card inflicts battle damage to your opponent: Declare 1 card name; look at your opponent''s hand, and if you do, discard all cards with that name in their hand.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (819, N'MFC', 46303688, N'MFC-025', N'Roulette Barrel', N'Effect Monster', 1000, 2000, 4, N'LIGHT', N'Machine', N'Once per turn: You can roll a six-sided die twice, choose 1 result, and destroy 1 monster on the field whose Level is equal to that result.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (820, N'MFC', 73398797, N'MFC-026', N'Paladin of White Dragon', N'Ritual Effect Monster', 1900, 1200, 4, N'LIGHT', N'Dragon', N'You can Ritual Summon this card with "White Dragon Ritual". At the start of the Damage Step, if this card attacks a face-down Defense Position monster: Destroy that face-down monster. You can Tribute this card; Special Summon 1 "Blue-Eyes White Dragon" from your hand or Deck, but "Blue-Eyes White Dragons" cannot attack for the rest of this turn.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (821, N'MFC', 9786492, N'MFC-027', N'White Dragon Ritual', N'Ritual Spell', NULL, NULL, 0, N'SPELL', N'Ritual', N'This card is used to Ritual Summon "Paladin of White Dragon". You must also Tribute monsters from your hand or field whose total Levels equal 4 or more.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (822, N'MFC', 46181000, N'MFC-028', N'Frontline Base', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'Once per turn: You can Special Summon 1 Level 4 or lower Union monster from your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (823, N'MFC', 72575145, N'MFC-029', N'Demotion', N'Equip Spell', NULL, NULL, 0, N'SPELL', N'Equip', N'Downgrade the monster equipped with this card by 2 Levels.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (824, N'MFC', 8964854, N'MFC-030', N'Combination Attack', N'Quick-Play Spell', NULL, NULL, 0, N'SPELL', N'Quick-Play', N'During a Battle Phase, you can use this effect on 1 monster that has attacked this turn and is equipped with a Union Monster. Change the Union Monster back to a monster in face-up Attack or Defense Position. Also, the monster that was equipped with the Union Monster may attack again this turn.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (825, N'MFC', 35059553, N'MFC-031', N'Kaiser Colosseum', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'If there is 1 or more monster(s) on the field of the controller of this card, his/her opponent cannot place a monster on the field if his/her number of monsters would exceed the number of monsters that are on the field of this card''s controller. The cards that are already on the field before this card''s activation are unaffected by this effect.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (826, N'MFC', 71453557, N'MFC-032', N'Autonomous Action Unit', N'Equip Spell', NULL, NULL, 0, N'SPELL', N'Equip', N'Pay 1500 Life Points, then target 1 monster in your opponent''s Graveyard; Special Summon that target to your side of the field in face-up Attack Position, and equip it with this card. When this card leaves the field, destroy the equipped monster.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
    (827, N'MFC', 8842266, N'MFC-033', N'Poison of the Old Man', N'Quick-Play Spell', NULL, NULL, 0, N'SPELL', N'Quick-Play', N'Activate 1 of these effects;
