    (940, N'DCR', 68304813, N'DCR-038', N'Precious Cards from Beyond', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'When you Tribute Summon a monster using 2 or more Tributes: Draw 2 cards.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:09'),
