INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (1001, N'DCR', 56246017, N'DCR-099', N'Archfiend''s Roar', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'Pay 500 Life Points, then target 1 "Archfiend" monster in your Graveyard; Special Summon that target. It cannot be Tributed. Destroy it during the End Phase of this turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1002, N'DCR', 83241722, N'DCR-100', N'Dice Re-Roll', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'One time, during the rest of this turn, if either player(s) rolls a die (or dice), you can have the player(s) re-roll. (You can only gain this effect once per turn.)', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1003, N'DCR', 29735721, N'DCR-101', N'Spell Vanishing', N'Counter Trap', NULL, NULL, 0, N'TRAP', N'Counter', N'Discard 2 cards from your hand. Negate the activation of a Spell Card and destroy it. Also, look at your opponent''s hand and Deck and if you find any Spell Cards of the same name as the destroyed Spell Card, send all of them to the Graveyard.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1004, N'DCR', 56120475, N'DCR-102', N'Sakuretsu Armor', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'When an opponent''s monster declares an attack: Target the attacking monster; destroy that target.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1005, N'DCR', 82529174, N'DCR-103', N'Ray of Hope', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'Add 2 LIGHT monsters from your Graveyard to your Deck and shuffle it.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1006, N'DCR', 89041555, N'DCR-104', N'Blast Held by a Tribute', N'Normal Trap', NULL, NULL, 0, N'TRAP', N'Normal', N'When an opponent''s monster that was Tribute Summoned declares an attack: Destroy as many face-up Attack Position monsters they control as possible, and if you do, inflict 1000 damage to your opponent.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1007, N'DCR', 55256016, N'DCR-105', N'Judgment of Anubis', N'Counter Trap', NULL, NULL, 0, N'TRAP', N'Counter', N'When your opponent activates a Spell Card that would destroy a Spell/Trap Card(s) on the field: Discard 1 card; negate the activation, and if you do, destroy it, then you can destroy 1 face-up monster your opponent controls, and if you do that, inflict damage to your opponent equal to the destroyed monster''s ATK on the field.', N'SECRET_RARE', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1008, N'IOC', 82301904, N'IOC-000', N'Chaos Emperor Dragon - Envoy of the End', N'Effect Monster', 3000, 2500, 8, N'DARK', N'Dragon', N'Cannot be Normal Summoned/Set. Must be Special Summoned (from your hand) by banishing 1 LIGHT and 1 DARK monster from your GY. Once per turn: You can pay 1000 LP; send as many cards in both players'' hands and on the field as possible to the GY, then inflict 300 damage to your opponent for each card sent to the opponent''s GY by this effect. You cannot activate other cards or effects during the turn you activate this card''s effect.', N'SECRET_RARE', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1009, N'IOC', 42941100, N'IOC-001', N'Ojama Yellow', N'Normal Monster', 0, 1000, 2, N'LIGHT', N'Beast', N'He''s one of the Ojama Trio. It''s said that he butts in by any means necessary. It''s also said that when the three are together, something happens.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1010, N'IOC', 79335209, N'IOC-002', N'Ojama Black', N'Normal Monster', 0, 1000, 2, N'LIGHT', N'Beast', N'He''s one of the Ojama Trio. It''s said that he butts in by any means necessary. It''s also said that when the three are together, something happens.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1011, N'IOC', 15734813, N'IOC-003', N'Soul Tiger', N'Normal Monster', 0, 2100, 4, N'EARTH', N'Beast', N'The soul of a tiger that is said to devour human souls. He is a famous soul that you wouldn''t want to run into in a dark alley.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1012, N'IOC', 42129512, N'IOC-004', N'Big Koala', N'Normal Monster', 2700, 2000, 7, N'EARTH', N'Beast', N'A species of huge Des Koala. He''s meek, but people are afraid of him because he''s very powerful.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
