INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (1201, N'AST', 43714890, N'AST-081', N'Man-Thro'' Tro''', N'Effect Monster', 1000, 1000, 4, N'EARTH', N'Beast-Warrior', N'By Tributing 1 Normal Monster (except a Token) on your side of the field, inflict 800 points of damage to your opponent''s Life Points.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1202, N'AST', 79109599, N'AST-082', N'King of the Swamp', N'Effect Monster', 500, 1100, 3, N'WATER', N'Aqua', N'This card can be used as a substitute for any 1 Fusion Material whose name is specifically listed on the Fusion Monster Card, but the other Fusion Material(s) must be correct. You can discard this card to the Graveyard; add 1 "Polymerization" from your Deck to your hand.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1203, N'AST', 6103294, N'AST-083', N'Emissary of the Oasis', N'Effect Monster', 600, 400, 3, N'LIGHT', N'Spellcaster', N'While a face-up Level 3 or lower Normal Monster is on your side of the field, your opponent cannot select this card as an attack target. While this card is face-up on your side of the field, any Battle Damage to the controller of this card from battle involving a Level 3 or lower Normal Monster becomes 0.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1204, N'AST', 42598242, N'AST-084', N'Special Hurricane', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'Discard 1 card from your hand. Destroy all Special Summoned monsters on the field.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1205, N'AST', 78986941, N'AST-085', N'Order to Charge', N'Quick-Play Spell', NULL, NULL, 0, N'SPELL', N'Quick-Play', N'Target 1 non-Token Normal Monster you control; Tribute that Normal Monster, and if you do, destroy 1 monster your opponent controls.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1206, N'AST', 5371656, N'AST-086', N'Sword of the Soul-Eater', N'Equip Spell', NULL, NULL, 0, N'SPELL', N'Equip', N'You can only equip this card to a Level 3 or lower Normal Monster on your side of the field. When you activate this card, Tribute all Normal Monsters (except Tokens) on your side of the field, except the equipped monster. Increase the ATK of the equipped monster by 1000 points for each Normal Monster that you Tributed.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1207, N'AST', 31476755, N'AST-087', N'Dust Barrier', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'Face-up Normal Monsters on the field are unaffected by your opponent''s Spell Cards. This card is destroyed during your second Standby Phase after activation.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1208, N'AST', 78864369, N'AST-088', N'Soul Reversal', N'Quick-Play Spell', NULL, NULL, 0, N'SPELL', N'Quick-Play', N'Return 1 Flip Effect Monster from your Graveyard to the top of your Deck.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:10'),
    (1209, N'AST', 4259068, N'AST-089', N'Spell Economics', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'You do not pay Life Points to activate Spell Cards.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1210, N'AST', 30653113, N'AST-090', N'Blessings of the Nile', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'Each time card(s) are discarded from your hand to the Graveyard by the effect of a card controlled by your opponent, increase your Life Points by 1000 points.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1211, N'AST', 67048711, N'AST-091', N'7', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'When there are 3 face-up "7" cards on your side of the field, draw 3 cards from your Deck. Then destroy all "7" cards. When this card is sent directly from the field to your Graveyard, increase your Life Points by 700 points.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1212, N'AST', 3136426, N'AST-092', N'Level Limit - Area B', N'Continuous Spell', NULL, NULL, 0, N'SPELL', N'Continuous', N'Change all face-up Level 4 or higher monsters to Defense Position.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1213, N'AST', 30531525, N'AST-093', N'Enchanting Fitting Room', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'Pay 800 LP; excavate the top 4 cards of your Deck and Special Summon all excavated Level 3 or lower Normal Monsters, also, after that, shuffle the rest back into your Deck.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1214, N'AST', 66926224, N'AST-094', N'The Law of the Normal', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'You can only activate this card while there are 5 face-up Level 2 or lower Normal Monsters on your side of the field. Both players discard all cards in their hands, and destroy all cards on the field except Level 2 or lower Normal Monsters.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1215, N'AST', 2314238, N'AST-095', N'Dark Magic Attack', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'If you control "Dark Magician": Destroy all Spells and Traps your opponent controls.', N'ULTRA_RARE', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1216, N'AST', 39719977, N'AST-096', N'Delta Attacker', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'You can only activate this card while there are 3 Normal Monsters of the same name (except Tokens) on your side of the field. The 3 Normal Monsters of the same name can attack your opponent''s Life Points directly during the turn this card is activated.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1217, N'AST', 5703682, N'AST-097', N'Thousand Energy', N'Normal Spell', NULL, NULL, 0, N'SPELL', N'Normal', N'Increase the original ATK and DEF of all face-up Level 2 Normal Monsters (except Tokens) on your side of the field by 1000 points until the End Phase. Destroy all Level 2 Normal Monsters on your side of the field during the End Phase.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:11'),
