INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (1401, N'EEN', 18271561, N'EEN-EN050', N'Chthonian Blast', N'Normal Trap Card', NULL, NULL, NULL, NULL, NULL, N'When a face-up monster you control is destroyed and sent to the Graveyard: Destroy the 1 face-up monster on the field that has the lowest ATK (your choice, if tied), and if you do, inflict damage to both players equal to half of that monster''s ATK.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1402, N'EEN', 29826127, N'EEN-EN051', N'The Forces of Darkness', N'Normal Trap Card', NULL, NULL, NULL, NULL, NULL, N'Target 2 "Dark World" monsters in your GY; add those targets to your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
    (1403, N'EEN', 65824822, N'EEN-EN052', N'Dark Deal', N'Normal Trap Card', NULL, NULL, NULL, NULL, NULL, N'When your opponent activates a Normal Spell Card: Pay 1000 LP; the activated effect of that Normal Spell becomes "Your opponent discards 1 random card".', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:11'),
