    (1604, N'CDIP', 12694768, N'CDIP-EN013', N'Abaki', N'Effect Monster', 1700, 1100, 4, N'FIRE', N'Fiend', N'When this card is destroyed and sent to the Graveyard by battle, both players take 500 damage.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:12'),
    (1605, N'CDIP', 58098303, N'CDIP-EN014', N'Flame Ogre', N'Effect Monster', 2400, 1700, 7, N'FIRE', N'Fiend', N'This card cannot be Special Summoned. When this card is Normal Summoned, draw 1 card.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:12'),
    (1606, N'CDIP', 84290642, N'CDIP-EN015', N'Snipe Hunter', N'Effect Monster', 1500, 600, 4, N'DARK', N'Fiend', N'You can discard 1 card, then target 1 card on the field; roll a six-sided die, and destroy that target unless you roll a 1 or 6.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:12'),
    (1607, N'CDIP', 11685347, N'CDIP-EN016', N'Blast Asmodian', N'Effect Monster', 1000, 300, 3, N'FIRE', N'Fiend', N'If any Spell or Trap Card(s) are Chained, inflict 500 damage to your opponent.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:12'),
