INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (2001, N'PTDN', 12735388, N'PTDN', N'Rainbow Veil', N'Spell', NULL, NULL, NULL, NULL, N'Equip', N'If the equipped monster battles an opponent''s monster, while that monster is on the field its effect(s) is negated during the Battle Phase only.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2002, N'PTDN', 48130397, N'PTDN', N'Super Polymerization', N'Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Discard 1 card; Fusion Summon 1 Fusion Monster from your Extra Deck, using monsters from either field as Fusion Material. Neither player can activate cards or effects in response to this card''s activation.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2003, N'PTDN', 75524092, N'PTDN', N'Vicious Claw', N'Spell', NULL, NULL, NULL, NULL, N'Equip', N'The equipped monster gains 300 ATK. If the equipped monster would be destroyed by battle, return this card to its owner''s hand instead. Then, destroy 1 monster, except the one that battled the equipped monster, and inflict 600 damage to your opponent. After that, Special Summon 1 "Evil Token" (Fiend-Type/DARK/Level 7/ATK 2500/DEF 2500) on your opponent''s side of the field. During the turn this card is returned to your hand, you cannot use "Vicious Claw" from your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2004, N'PTDN', 11913700, N'PTDN', N'Instant Neo Space', N'Spell', NULL, NULL, NULL, NULL, N'Equip', N'Equip only to a Fusion Monster that lists "Elemental HERO Neos" as material. It does not have to activate its effect during the End Phase to shuffle itself into the Extra Deck. If the equipped monster leaves the field: You can Special Summon 1 "Elemental HERO Neos" from your hand, Deck, or GY.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2005, N'PTDN', 48017809, N'PTDN', N'Mirage Tube', N'Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'This card cannot be activated from your hand. Activate only when a face-up monster you control is selected as an attack target. Inflict 1000 damage to your opponent.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2006, N'PTDN', 74402414, N'PTDN', N'Spell Chronicle', N'Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Activate this card by sending your entire hand to the GY; banish 5 Spells/Traps from your Deck. Each time your opponent activates a Spell Card, place 1 Chronicle Counter on this card when that Spell Card resolves. You can remove 2 Chronicle Counters from this card; your opponent chooses 1 card banished by this card''s effect for you to add to your hand. If this face-up card in the Spell & Trap Zone leaves the field: You take 500 damage for each card currently banished by this card''s effect.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2007, N'PTDN', 1896112, N'PTDN', N'Dimension Explosion', N'Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Return 1 face-up Fusion Monster you control to the Extra Deck. Both players select up to 2 of their monsters that are removed from play, and Special Summon them.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2008, N'PTDN', 47295267, N'PTDN', N'Cybernetic Zone', N'Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Select 1 face-up Machine-Type Fusion Monster you control and remove it from play until the End Phase of this turn. When that monster is returned to the field, double its ATK. During your next Standby Phase, destroy it.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2009, N'PTDN', 73680966, N'PTDN', N'The Beginning of the End', N'Spell', NULL, NULL, NULL, NULL, N'Normal', N'If you have 7 or more DARK monsters in your GY: Banish 5 DARK monsters from your GY; draw 3 cards.', N'ULTRA RARE', 1, 1, 1, 1, '2026-10-12 12:22:14'),
    (2010, N'PTDN', 674561, N'PTDN', N'Dark Eruption', N'Spell', NULL, NULL, NULL, NULL, N'Normal', N'Target 1 DARK monster with 1500 or less ATK in your GY; add that target to your hand.', N'SUPER RARE', 1, 1, 1, 1, '2026-10-12 12:22:14'),
