INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (2401, N'CRMS', 94303232, N'CRMS-EN045', N'Prevention Star', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'Equip only to a monster you control, if it was changed from face-up Attack Position to face-up Defense Position this turn. Select 1 monster your opponent controls. That monster cannot attack or change its battle position. When the equipped monster is destroyed and this card is sent to the Graveyard, remove from play the selected monster.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2402, N'CRMS', 21702241, N'CRMS-EN046', N'Vengeful Servant', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'When control of the equipped monster changes, inflict damage equal to its original ATK to its new controller.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2403, N'CRMS', 67196946, N'CRMS-EN047', N'Star Blast', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Pay any number of Life Points in multiples of 500; reduce the Level of 1 monster you control or that is in your hand by 1 for each 500 Life Points you paid, until the End Phase.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2404, N'CRMS', 94681654, N'CRMS-EN048', N'Raptor Wing Strike', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Shuffle 1 "Blackwing" monster you control into the Main Deck; add 1 "Blackwing" monster from your Deck to your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2405, N'CRMS', 20686759, N'CRMS-EN049', N'Morphtronic Rusty Engine', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'Equip only to a "Morphtronic" monster. If the equipped monster is destroyed, inflict damage to each player equal to its original ATK.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2406, N'CRMS', 56074358, N'CRMS-EN050', N'Morphtronic Map', N'Field Spell', NULL, NULL, NULL, NULL, N'Field', N'Each time a monster''s battle position is changed, place 1 Morph Counter on this card. All "Morphtronic" monsters gain 300 ATK for each Morph Counter on this card. When this card is destroyed and sent from the field to the Graveyard, you can Special Summon 1 "Morphtronic" monster from your Graveyard.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2407, N'CRMS', 93469007, N'CRMS-EN051', N'Assault Overload', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Tribute 1 "/Assault Mode" monster. Inflict damage to both players equal to its Level x 200.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2408, N'CRMS', 29863101, N'CRMS-EN052', N'Assault Teleport', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Return 1 "/Assault Mode" monster from your hand to the Deck. Draw 2 cards.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2409, N'CRMS', 56252810, N'CRMS-EN053', N'Assault Revival', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Remove from play 1 "Assault Mode Activate" from your Graveyard. Destroy all monsters you control and Special Summon 1 "/Assault Mode" monster from your Graveyard, ignoring its Summoning conditions. Its effect(s) is negated, and it cannot be Tributed. If it is removed from the field, remove it from play.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2410, N'CRMS', 92346415, N'CRMS-EN054', N'Psychic Sword', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'Equip only to a Psychic-Type monster. While your LP is lower than your opponent''s, the equipped monster gains ATK equal to the difference (max. 2000).', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2411, N'CRMS', 28741524, N'CRMS-EN055', N'Telekinetic Power Well', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Special Summon any number of Level 2 or lower Psychic-Type monsters from your Graveyard. You take damage equal to the total Levels of those monsters x 300.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2412, N'CRMS', 55136228, N'CRMS-EN056', N'Indomitable Gladiator Beast', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Target face-up "Gladiator Beast" monster you control gains 500 ATK until the End Phase. While this card is in your Graveyard, you can return 2 "Gladiator Beast" cards from your Graveyard to the Deck to return this card to your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2413, N'CRMS', 81524977, N'CRMS-EN057', N'Seed Cannon', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Each time a Plant-Type monster(s) is Summoned, place 1 Plant Counter on this card (max. 5). You can send this card to the Graveyard to inflict 500 damage to your opponent for each Plant Counter on it.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2414, N'CRMS', 28529976, N'CRMS-EN058', N'Super Solar Nutrient', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Activate this card by Tributing 1 Level 2 or lower Plant-Type monster; Special Summon 1 Plant-Type monster from your hand or Deck whose Level is less than or equal to the Level the Tributed monster had on the field +3. When this card leaves the field, destroy that monster. When that monster leaves the field, destroy this card.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2415, N'CRMS', 54913680, N'CRMS-EN059', N'Six Scrolls of the Samurai', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Tribute 2 face-up "Six Samurai" monsters. Special Summon 1 "Great Shogun Shien" from your Deck.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2416, N'CRMS', 80402389, N'CRMS-EN060', N'Verdant Sanctuary', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'When a face-up Insect monster is destroyed by battle or card effect and sent to the GY: Its controller can add 1 Insect monster with the same Level as the destroyed monster from their Deck to their hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2417, N'CRMS', 17896384, N'CRMS-EN061', N'Arcane Barrier', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Each time a face-up Spellcaster monster(s) on the field is destroyed, place 1 Spell Counter on this card (max. 4). You can send this card and 1 face-up Spellcaster monster you control to the GY; draw 1 card for each Spell Counter that was on this card.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2418, N'CRMS', 53291093, N'CRMS-EN062', N'Mysterious Triangle', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Destroy 1 monster on the field with an A-Counter. Then, you can Special Summon 1 Level 4 "Alien" monster from your Deck. Destroy it during the End Phase.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2419, N'CRMS', 80280737, N'CRMS-EN063', N'Assault Mode Activate', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Tribute 1 Synchro Monster; Special Summon 1 "/Assault Mode" monster, whose name includes the Tributed monster''s name, from your Deck in Attack Position.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2420, N'CRMS', 16674846, N'CRMS-EN064', N'Spirit Force', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'During your opponent''s turn, at damage calculation: Make the battle damage you take from this battle 0, then you can add 1 Warrior-Type Tuner monster with 1500 or less DEF from your Graveyard to your hand.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2421, N'CRMS', 42079445, N'CRMS-EN065', N'Descending Lost Star', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Target 1 Synchro Monster in your Graveyard; Special Summon that target in Defense Position, but its effects are negated, its Level is reduced by 1, its DEF becomes 0, also its battle position cannot be changed.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2422, N'CRMS', 89563150, N'CRMS-EN066', N'Shining Silver Force', N'Counter Trap', NULL, NULL, NULL, NULL, N'Counter', N'Activate only when your opponent activates a Trap Card that inflicts damage. Negate the activation of that card and destroy it and all face-up Spell and Trap Cards your opponent controls.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2423, N'CRMS', 15552258, N'CRMS-EN067', N'Half or Nothing', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'During your opponent''s Battle Phase (except during the Damage Step): Your opponent chooses 1 of these effects.
● Halve the ATK of all monsters they currently control, until the end of the Battle Phase.
● End the Battle Phase.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2424, N'CRMS', 42956963, N'CRMS-EN068', N'Nightmare Archfiends', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Tribute 1 monster; Special Summon 3 "Nightmare Archfiend Tokens" (Fiend-Type/DARK/Level 6/ATK 2000/DEF 2000) to your opponent''s field in Attack Position. Each time 1 is destroyed, its controller takes 800 damage.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
    (2425, N'CRMS', 88341502, N'CRMS-EN069', N'Ebon Arrow', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Select 1 face-up monster you control. Until the End Phase, it loses 500 ATK and during battle between that attacking monster and a Defense Position monster whose DEF is lower than the selected monster''s ATK, inflict the difference as Battle Damage to your opponent. When the selected monster destroys a monster by battle and sends it to the Graveyard this turn, inflict damage to your opponent equal to the destroyed monster''s original DEF.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:15'),
