INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (2801, N'ABPF', 39701395, N'ABPF-EN045', N'Cards of Consonance', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Discard 1 Dragon Tuner with 1000 or less ATK; draw 2 cards.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2802, N'ABPF', 65196094, N'ABPF-EN046', N'Variety Comes Out', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Return 1 face-up Synchro Monster you control to the Extra Deck to select and Special Summon a Tuner monster(s) from your Graveyard, whose total Levels equal the Level of that Synchro Monster. You cannot Synchro Summon the turn you activate this card.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2803, N'ABPF', 91580102, N'ABPF-EN047', N'Reptilianne Rage', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'The equipped monster becomes Reptile-Type. It gains 800 ATK. If this card is destroyed and sent to the Graveyard: Target 1 face-up monster your opponent controls; it loses 800 ATK.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2804, N'ABPF', 38589847, N'ABPF-EN048', N'Advance Force', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'You can Tribute 1 Level 5 or higher monster to Tribute Summon a Level 7 or higher monster.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2805, N'ABPF', 64973456, N'ABPF-EN049', N'Viper''s Rebirth', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Activate only if all monsters in your Graveyard are Reptile-Type. Select 1 non-Tuner monster in your Graveyard. Special Summon it. Destroy it during the End Phase.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2806, N'ABPF', 91468551, N'ABPF-EN050', N'Temple of the Sun', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Face-up monsters you control that were Special Summoned from the Graveyard gain 300 ATK.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2807, N'ABPF', 27863269, N'ABPF-EN051', N'Rocket Pilder', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'While the equipped monster is attacking, it cannot be destroyed by battle. At the end of the Damage Step, if the equipped monster attacked: The attack target loses ATK equal to the ATK of the equipped monster, until the End Phase.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2808, N'ABPF', 63851864, N'ABPF-EN052', N'Break! Draw!', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'Equip only to a Machine monster. If the equipped monster destroys an opponent''s monster by battle and sends it to the GY: Draw 1 card. Destroy this card during your 3rd End Phase after activation.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2809, N'ABPF', 90246973, N'ABPF-EN053', N'Power Pickaxe', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'Once per turn, you can select and remove from play 1 monster in your opponent''s Graveyard whose Level is less than or equal to the equipped monster''s, and have the equipped monster gain 500 ATK until the End Phase.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2810, N'ABPF', 26640671, N'ABPF-EN054', N'Spiders'' Lair', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Once per turn, you can select 1 face-up Insect-Type monster you control. While this card remains on the field, any opponent''s monster that battles with one of those monsters is changed to Defense Position at the end of the Battle Phase, and cannot change its battle position while this card is on the field.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2811, N'ABPF', 53039326, N'ABPF-EN055', N'Iron Core Specimen Lab', N'Field Spell', NULL, NULL, NULL, NULL, N'Field', N'During each of your End Phases, destroy this card unless you reveal 1 "Iron Core of Koa''ki Meiru" in your hand. Each time a "Koa''ki Meiru" monster on the field is destroyed during the End Phase, its owner can add 1 "Koa''ki Meiru" monster from their Deck to their hand.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2812, N'ABPF', 99523325, N'ABPF-EN056', N'Gravekeeper''s Stele', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Target 2 "Gravekeeper''s" monsters in your GY; add those targets to your hand. This effect cannot be negated by the effect of "Necrovalley".', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2813, N'ABPF', 25518020, N'ABPF-EN057', N'Machine Assembly Line', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'All Machine-Type monsters on the field gain 200 ATK. Each time a face-up Machine-Type monster(s) on the field is destroyed by battle or card effect, place 2 Junk Counters on this card. You can send this card to the Graveyard, then target 1 Machine-Type monster in your Graveyard whose Level is less than or equal to the number of Junk Counters that were on this card; Special Summon that target.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2814, N'ABPF', 52913738, N'ABPF-EN058', N'Ritual of Destruction', N'Ritual Spell', NULL, NULL, NULL, NULL, N'Ritual', N'This card is used to Ritual Summon "Garlandolf, King of Destruction". You must also Tribute monsters whose total Levels equal 7 or more from the field or your hand. During your Main Phase, you can remove from play this card from your Graveyard. If you do, during this turn, any monster destroyed by battle with a Ritual Monster you control will be returned to the top of the Deck instead of being sent to the Graveyard.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2815, N'ABPF', 88301833, N'ABPF-EN059', N'Ascending Soul', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Once per turn, when a Ritual Monster(s) is Ritual Summoned: You can target 1 monster in your Graveyard that was Tributed for the Ritual Summon; add that target to your hand.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2816, N'ABPF', 25796442, N'ABPF-EN060', N'Ritual Cage', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'You take no battle damage from attacks involving a Ritual Monster you control. Ritual Monsters you control cannot be targeted by, or destroyed by, monster effects.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2817, N'ABPF', 51790181, N'ABPF-EN061', N'Pot of Benevolence', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Select 2 cards from the Graveyard(s), and shuffle them into their owner''s Deck(s). After activation, remove this card from play instead of sending it to the Graveyard. You can only activate 1 "Pot of Benevolence" per turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2818, N'ABPF', 88289295, N'ABPF-EN062', N'Synchro Control', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Activate only if you have no Synchro Monsters on your side of the field or in your Graveyard. Pay 1000 Life Points and select 1 face-up Synchro Monster your opponent controls. Take control of the selected monster until the End Phase of your turn.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2819, N'ABPF', 24673894, N'ABPF-EN063', N'Changing Destiny', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'When an opponent''s monster declares an attack: Target the attacking monster; negate the attack, and if you do, change it to Defense Position and it cannot change its battle position while it is face-up on the field. Then, your opponent chooses 1 of these effects.
● You (the opponent of this card''s activator) gain LP equal to half the target''s ATK.
● Your opponent (the activator of this card) takes damage equal to half the target''s ATK.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2820, N'ABPF', 50078509, N'ABPF-EN064', N'Fiendish Chain', N'Continuous Trap', NULL, NULL, NULL, NULL, N'Continuous', N'Activate this card by targeting 1 Effect Monster on the field; negate the effects of that face-up monster while it is on the field, also that face-up monster cannot attack. When it is destroyed, destroy this card.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2821, N'ABPF', 83467607, N'ABPF-EN065', N'Nature''s Reflection', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'During this turn, any effect activated by your opponent that would inflict damage becomes an effect that inflicts damage to their Life Points.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2822, N'ABPF', 19451302, N'ABPF-EN066', N'Serpent Suppression', N'Continuous Trap', NULL, NULL, NULL, NULL, N'Continuous', N'Face-up Attack Position monsters with 0 ATK your opponent controls cannot be destroyed by battle with "Reptilianne" monsters.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2823, N'ABPF', 56856951, N'ABPF-EN067', N'Meteor Flare', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Activate by sending 2 cards from your hand to the Graveyard while your opponent has more than 3000 Life Points. Inflict 2000 damage to your opponent. If this card is in the Graveyard, you can add it to your hand instead of conducting your normal draw during your Draw Phase.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2824, N'ABPF', 82340056, N'ABPF-EN068', N'Offering to the Immortals', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'When your opponent''s monster declares a direct attack while you have 3000 or less LP: Negate the attack, and if you do, Special Summon 2 "Ceremonial Tokens" (Rock-Type/EARTH/Level 1/ATK 0/DEF 0), and if you do that, add 1 "Earthbound Immortal" card, "Earthbound Revival", or "Roar of the Earthbound" from your Deck to your hand. "Ceremonial Tokens" cannot be Tributed, except for a Tribute Summon of an "Earthbound Immortal" monster, and cannot be used as Synchro Material.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2825, N'ABPF', 18739764, N'ABPF-EN069', N'Destruct Potion', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Select 1 monster you control. Destroy it, and gain Life Points equal to its ATK.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2826, N'ABPF', 45133463, N'ABPF-EN070', N'Call of the Reaper', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Activate only when a monster(s) is Special Summoned from your Graveyard. Select and Special Summon 1 "Supay" or 1 "Fire Ant Ascator" from your Graveyard.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2827, N'ABPF', 81128478, N'ABPF-EN071', N'Lair Wire', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Remove from play 1 Insect-Type monster from your Graveyard and select 1 monster your opponent controls. Destroy the selected monster.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:16'),
    (2828, N'ABPF', 18517177, N'ABPF-EN072', N'Core Blast', N'Continuous Trap', NULL, NULL, NULL, NULL, N'Continuous', N'You can only activate this card''s effect while you control a face-up "Koa''ki Meiru" monster. Once per turn, during your Standby Phase, if your opponent controls more monsters than you do, you can destroy a number of cards your opponent controls so that your opponent will control the same number of cards as you control monsters.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:16'),
