INSERT INTO [dbo].[BoosterPackCards] ([Id], [PackId], [CardId], [CardNumber], [CardName], [CardType], [Atk], [Def], [Level], [Attribute], [Race], [Description], [Rarity], [IsActive], [PackDrop], [DeckUsable], [NpcDrop], [CreatedAt]) VALUES
    (3201, N'STOR', 55154048, N'STOR-EN045', N'Nordic Relic Draupnir', N'Equip Spell', NULL, NULL, NULL, NULL, N'Equip', N'Equip only to an "Aesir" or "Nordic" monster. It gains 800 ATK. If this face-up card on the field is destroyed by a card effect: You can add 1 "Nordic Relic" card from your Deck to your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3202, N'STOR', 91148083, N'STOR-EN046', N'Gotterdammerung', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Target 1 "Aesir" monster you control; give control of that monster to your opponent. During your opponent''s next End Phase, destroy that monster, and if you do, banish all cards your opponent controls.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3203, N'STOR', 28643791, N'STOR-EN047', N'March Towards Ragnarok', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Target 1 "Aesir" monster you control; until the end of this turn, its effects are negated, also that face-up monster is unaffected by the effects of other Spells/Traps.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3204, N'STOR', 54031490, N'STOR-EN048', N'Shien''s Smoke Signal', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Add 1 Level 3 or lower "Six Samurai" monster from your Deck to your hand.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3205, N'STOR', 81426505, N'STOR-EN049', N'Six Strike - Triple Impact', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'If you control 3 or more face-up "Six Samurai" monsters, you can activate 1 of these effects:
● Destroy all face-up monsters your opponent controls.
● Destroy all face-up Spell/Trap Cards your opponent controls.
● Destroy all Set Spell/Trap Cards your opponent controls.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3206, N'STOR', 27821104, N'STOR-EN050', N'Asceticism of the Six Samurai', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Target 1 "Six Samurai" monster you control; Special Summon 1 "Six Samurai" monster from your Deck with the same ATK but a different name, and if you do, destroy it during the End Phase of this turn.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3207, N'STOR', 53819808, N'STOR-EN051', N'Temple of the Six', N'Field Spell', NULL, NULL, NULL, NULL, N'Field', N'Each time a "Six Samurai" monster(s) is Normal or Special Summoned, place 1 Bushido Counter on this card. Monsters your opponent controls lose 100 ATK for each Bushido Counter on this card.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3208, N'STOR', 80204957, N'STOR-EN052', N'Karakuri Cash Cache', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Select 1 face-up "Karakuri" monster you control. Add 1 Level 4 or lower "Karakuri" monster from your Deck to your hand and change the battle position of the selected monster.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3209, N'STOR', 16708652, N'STOR-EN053', N'Karakuri Gold Dust', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Activate only during the Battle Phase. Select 2 face-up "Karakuri" monsters in Attack Position. Change 1 of the selected monsters to Defense Position, and the other gains ATK equal to the ATK of the monster changed to Defense Position, until the End Phase.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3210, N'STOR', 53193261, N'STOR-EN054', N'Wattkey', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Face-up "Watt" monsters you control can attack your opponent directly this turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3211, N'STOR', 89181369, N'STOR-EN055', N'Stardust Shimmer', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Select 1 Dragon-Type Synchro Monster in your Graveyard. Remove from play other monsters in your Graveyard whose total Levels equal the Level of the selected monster and Special Summon it from the Graveyard.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3212, N'STOR', 15576074, N'STOR-EN056', N'Resonator Engine', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Target 2 "Resonator" monsters in your Graveyard; add 1 Level 4 monster from your Deck to your hand, and if you do, return those targets to the Deck.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3213, N'STOR', 52971673, N'STOR-EN057', N'Token Sundae', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Destroy all Tokens you control, then destroy cards on the field up to the number of Tokens destroyed by this effect.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3214, N'STOR', 88369727, N'STOR-EN058', N'Foolish Return', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Select 1 card in your opponent''s Graveyard. Return it to the Deck.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3215, N'STOR', 15854426, N'STOR-EN059', N'Divine Wind of Mist Valley', N'Field Spell', NULL, NULL, NULL, NULL, N'Field', N'Once per turn, if a WIND monster you control returns to the hand (except during the Damage Step): You can Special Summon 1 Level 4 or lower WIND monster from your Deck.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3216, N'STOR', 41858121, N'STOR-EN060', N'Vylon Matter', N'Normal Spell', NULL, NULL, NULL, NULL, N'Normal', N'Select 3 Equip Spell Cards in your Graveyard. Return them to the Deck and apply 1 of these effects: ● Draw 1 card. ● Destroy 1 card your opponent controls.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3217, N'STOR', 27243130, N'STOR-EN061', N'Forbidden Lance', N'Quick-Play Spell', NULL, NULL, NULL, NULL, N'Quick-Play', N'Target 1 face-up monster on the field; until the end of this turn, that target loses 800 ATK, but is unaffected by the effects of other Spells/Traps.', N'SUPER_RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3218, N'STOR', 54631834, N'STOR-EN062', N'Terminal World', N'Continuous Spell', NULL, NULL, NULL, NULL, N'Continuous', N'Activate only during Main Phase 1. While this card is on the field, both players skip their Main Phase 2.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3219, N'STOR', 80036543, N'STOR-EN063', N'Hope for Escape', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'If your opponent''s LP is at least 1000 higher than yours: Pay 1000 LP; draw 1 card for every 2000 points difference between your LP and your opponent''s.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3220, N'STOR', 17521642, N'STOR-EN064', N'Zero Force', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Activate only when a face-up monster you control is removed from play. The ATK of all face-up monsters on the field becomes 0.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3221, N'STOR', 53519297, N'STOR-EN065', N'Blackboost', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Banish 2 face-up "Blackwing" Tuner monsters you control; draw 2 cards.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3222, N'STOR', 89914395, N'STOR-EN066', N'Divine Relic Mjollnir', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Target 1 "Aesir" monster you control; it can make a second attack during each Battle Phase this turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:17'),
    (3223, N'STOR', 16308000, N'STOR-EN067', N'Solemn Authority', N'Continuous Trap', NULL, NULL, NULL, NULL, N'Continuous', N'Activate this card by targeting 1 "Aesir" monster you control; it cannot be targeted by other card effects while this card is on the field. Send this card to the GY during your 2nd Standby Phase after activation.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3224, N'STOR', 42793609, N'STOR-EN068', N'Nordic Relic Brisingamen', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Target 1 face-up monster you control and 1 face-up monster your opponent controls; the ATK of the first target becomes equal to the original ATK of the second target, until the end of this turn.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3225, N'STOR', 89792713, N'STOR-EN069', N'Nordic Relic Laevateinn', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Target 1 face-up monster on the field that destroyed a monster by battle this turn; destroy it. Cards and effects cannot be activated in response to this card''s activation.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3226, N'STOR', 15286412, N'STOR-EN070', N'Nordic Relic Gungnir', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Banish 1 "Aesir" or "Nordic" monster you control, then target 1 card on the field; destroy it, also during your 2nd End Phase after activation, return the monster you banished to activate this card to the field in face-up Attack Position.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3227, N'STOR', 42671151, N'STOR-EN071', N'The Golden Apples', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'When you take battle damage while you control no monsters: Gain LP equal to the battle damage you took, and if you do, Special Summon 1 "Malus Token" (Fiend/DARK/Level 1/ATK ?/DEF ?). Its ATK/DEF are each equal to the amount of LP you gained by this effect.', N'SECRET_RARE', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3228, N'STOR', 88069166, N'STOR-EN072', N'Odin''s Eye', N'Continuous Trap', NULL, NULL, NULL, NULL, N'Continuous', N'Once per turn, during each player''s Standby Phase: You can target 1 "Aesir" monster you control; negate its effects until the end of this turn, and if you do, look at all cards in your opponent''s hand and all Set cards they control. Your opponent cannot activate cards or effects in response to this effect''s activation.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3229, N'STOR', 14464864, N'STOR-EN073', N'Gleipnir, the Fetters of Fenrir', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'Add 1 "Nordic" monster from your Deck to your hand.', N'SECRET_RARE', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3230, N'STOR', 41458579, N'STOR-EN074', N'Musakani Magatama', N'Counter Trap', NULL, NULL, NULL, NULL, N'Counter', N'When your opponent activates a Spell/Trap Card, or monster effect, that destroys a card(s), while you control a "Six Samurai" monster: Negate the activation, and if you do, destroy it.', N'RARE', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3231, N'STOR', 77847678, N'STOR-EN075', N'Shien''s Scheme', N'Normal Trap', NULL, NULL, NULL, NULL, N'Normal', N'If a "Six Samurai" monster you control is destroyed by battle: Special Summon up to 2 "Six Samurai" monsters from your hand.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:18'),
    (3232, N'STOR', 14342283, N'STOR-EN076', N'Token Stampede', N'Continuous Trap', NULL, NULL, NULL, NULL, N'Continuous', N'All Tokens in Attack Position gain 1000 ATK, also they cannot be destroyed by battle.', N'COMMON', 1, 1, 1, 1, '2026-10-12 12:22:18'),
