    (3372, N'PROMO-DM', 23995346, N'PROMO-001', N'Blue-Eyes Ultimate Dragon', N'Fusion Monster', 4500, 3800, 12, N'LIGHT', N'Dragon', N'"Blue-Eyes White Dragon" + "Blue-Eyes White Dragon" + "Blue-Eyes White Dragon"', N'SECRET_RARE', 1, 1, 1, 0, '2026-10-12 12:22:18'),
    (3373, N'PROMO-DM', 62873545, N'PROMO-002', N'Dragon Master Knight', N'Fusion Effect Monster', 5000, 5000, 12, N'LIGHT', N'Dragon', N'"Black Luster Soldier" + "Blue-Eyes Ultimate Dragon"
