-- PROCEDIMIENTO: [dbo].[sp_GetBoosterPacks]
-- ==========================================
IF OBJECT_ID('dbo.[sp_GetBoosterPacks]', 'P') IS NOT NULL DROP PROCEDURE dbo.[sp_GetBoosterPacks];
GO
CREATE   PROCEDURE dbo.sp_GetBoosterPacks
            AS
            BEGIN
                SET NOCOUNT ON;
                -- 1. Lista de sobres
                SELECT 
                    PackId, Name, Code, Series, Price, OfferText, Image, Description, CardsPerPack,
                    IsActive, IsVisible, UpdatedAt
                FROM dbo.BoosterPacks
                ORDER BY 
                    CASE WHEN PackId = 'LOB' THEN 0 ELSE 1 END,
                    PackId ASC;

                -- 2. Lista de overrides de cartas
                SELECT 
                    PackId, CardId, IsActive, PackDrop, DeckUsable, NpcDrop, UpdatedAt
                FROM dbo.PackCardOverrides;
            END;
GO

-- ==========================================
-- PROCEDIMIENTO: [dbo].[sp_GetCardInfo]
-- ==========================================
IF OBJECT_ID('dbo.[sp_GetCardInfo]', 'P') IS NOT NULL DROP PROCEDURE dbo.[sp_GetCardInfo];
GO
CREATE   PROCEDURE sp_GetCardInfo
            @CardId INT
        AS
        BEGIN
            SET NOCOUNT ON;

            SELECT 
                d.id,
                d.id AS card_id,
                d.ot,
                d.alias,
                d.setcode,
                d.type,
                d.type AS typeCode,
                d.atk,
                d.def,
                d.level,
                d.race,
                d.race AS raceCode,
                d.attribute,
                d.attribute AS attributeCode,
                d.category,
                t.name,
                COALESCE(NULLIF(t.name_es, ''), t.name) AS name_es,
                t.[desc] AS [desc],
                COALESCE(NULLIF(t.desc_es, ''), NULLIF(c.Description, ''), t.[desc]) AS desc_es,
                COALESCE(c.Rarity, 'COMMON') AS rarity,
                CASE 
                    WHEN c.ImageUrl LIKE 'http%' THEN c.ImageUrl
                    ELSE CONCAT('https://images.ygoprodeck.com/images/cards_small/', d.id, '.jpg')
                END AS image_url
            FROM datas d
            LEFT JOIN texts t ON d.id = t.id
            LEFT JOIN Cards c ON d.id = c.CardCode
            WHERE d.id = @CardId;
        END;
GO

