GO
CREATE   PROCEDURE dbo.sp_GetUserCards
                @UsuarioId INT
            AS
            BEGIN
                SET NOCOUNT ON;
                SELECT 
                    CardCode, 
                    SUM(Quantity) AS Quantity, 
                    MAX(FoilType) AS FoilType, 
                    MAX(AcquiredAt) AS AcquiredAt
                FROM dbo.UserCardsSql
                WHERE UsuarioId = @UsuarioId
                GROUP BY CardCode;
            END;
